<div class="row g-3 mb-4"><?php foreach (array('today_income' => '今日收入', 'month_income' => '本月收入', 'orders' => '今日订单', 'unpaid' => '待支付', 'failed' => '开通失败', 'cancel' => '取消申请', 'tickets' => '待处理工单') as $k => $label): ?><div class="col-6 col-md-3"><div class="kpi"><div class="v"><?=h(isset($stats[$k]) ? (in_array($k, array('today_income', 'month_income'), true) ? money($stats[$k]) : $stats[$k]) : 0)?></div><div class="l"><?=h($label)?></div></div></div><?php endforeach; ?></div><div class="card p-3"><h3 class="h6">最近订单</h3><div class="table-responsive"><table class="table table-sm"><tr><th>订单号</th><th>标题</th><th>状态</th><th>金额</th></tr><?php foreach ((array)$recent as $o): ?><tr><td><?=h($o['order_no'])?></td><td><?=h($o['title'])?></td><td><?=order_status_badge($o)?></td><td><?=h(money($o['pay_amount']))?></td></tr><?php endforeach; ?></table></div></div>
